   916→typedef int (*poll_pfn_t)(struct pollfd fds[], nfds_t nfds, int timeout);
   917→int co_poll_inner( stCoEpoll_t *ctx,struct pollfd fds[], nfds_t nfds, int timeout, poll_pfn_t pollfunc)
   918→{
   919→    if (timeout == 0)
   920→	{
   921→		return pollfunc(fds, nfds, timeout);
   922→	}
   923→	if (timeout < 0)
   924→	{
   925→		timeout = INT_MAX;
   926→	}
   927→	int epfd = ctx->iEpollFd;
   928→	stCoRoutine_t* self = co_self();
   929→
   930→	//1.struct change
   931→	stPoll_t& arg = *((stPoll_t*)malloc(sizeof(stPoll_t)));
   932→	memset( &arg,0,sizeof(arg) );
   933→
   934→	arg.iEpollFd = epfd;
   935→	arg.fds = (pollfd*)calloc(nfds, sizeof(pollfd));
   936→	arg.nfds = nfds;
   937→
   938→	stPollItem_t arr[2];
   939→	if( nfds < sizeof(arr) / sizeof(arr[0]) && !self->cIsShareStack)
   940→	{
   941→		arg.pPollItems = arr;
   942→	}	
   943→	else
   944→	{
   945→		arg.pPollItems = (stPollItem_t*)malloc( nfds * sizeof( stPollItem_t ) );
   946→	}
   947→	memset( arg.pPollItems,0,nfds * sizeof(stPollItem_t) );
   948→
   949→	arg.pfnProcess = OnPollProcessEvent;
   950→	arg.pArg = GetCurrCo( co_get_curr_thread_env() );
   951→	
   952→	
   953→	//2. add epoll
   954→	for(nfds_t i=0;i<nfds;i++)
   955→	{
   956→		arg.pPollItems[i].pSelf = arg.fds + i;
   957→		arg.pPollItems[i].pPoll = &arg;
   958→
   959→		arg.pPollItems[i].pfnPrepare = OnPollPreparePfn;
   960→		struct epoll_event &ev = arg.pPollItems[i].stEvent;
   961→
   962→		if( fds[i].fd > -1 )
   963→		{
   964→			ev.data.ptr = arg.pPollItems + i;
   965→			ev.events = PollEvent2Epoll( fds[i].events );
   966→
   967→			int ret = co_epoll_ctl( epfd,EPOLL_CTL_ADD, fds[i].fd, &ev );
   968→			if (ret < 0 && errno == EPERM && nfds == 1 && pollfunc != NULL)
   969→			{
   970→				if( arg.pPollItems != arr )
   971→				{
   972→					free( arg.pPollItems );
   973→					arg.pPollItems = NULL;
   974→				}
   975→				free(arg.fds);
   976→				free(&arg);
   977→				return pollfunc(fds, nfds, timeout);
   978→			}
   979→		}
   980→		//if fail,the timeout would work
   981→	}
   982→
   983→	//3.add timeout
   984→
   985→	unsigned long long now = GetTickMS();
   986→	arg.ullExpireTime = now + timeout;
   987→	int ret = AddTimeout( ctx->pTimeout,&arg,now );
   988→	int iRaiseCnt = 0;
   989→	if( ret != 0 )
   990→	{
   991→		co_log_err("CO_ERR: AddTimeout ret %d now %lld timeout %d arg.ullExpireTime %lld",
   992→				ret,now,timeout,arg.ullExpireTime);
   993→		errno = EINVAL;
   994→		iRaiseCnt = -1;
   995→
   996→	}
   997→    else
   998→	{
   999→		co_yield_env( co_get_curr_thread_env() );
  1000→		iRaiseCnt = arg.iRaiseCnt;
  1001→	}
  1002→
  1003→    {
  1004→		//clear epoll status and memory
  1005→		RemoveFromLink<stTimeoutItem_t,stTimeoutItemLink_t>( &arg );
  1006→		for(nfds_t i = 0;i < nfds;i++)
  1007→		{
  1008→			int fd = fds[i].fd;
  1009→			if( fd > -1 )
  1010→			{
  1011→				co_epoll_ctl( epfd,EPOLL_CTL_DEL,fd,&arg.pPollItems[i].stEvent );
  1012→			}
  1013→			fds[i].revents = arg.fds[i].revents;
  1014→		}
  1015→
  1016→
  1017→		if( arg.pPollItems != arr )
  1018→		{
  1019→			free( arg.pPollItems );
  1020→			arg.pPollItems = NULL;
  1021→		}
  1022→
  1023→		free(arg.fds);
  1024→		free(&arg);
  1025→	}
  1026→
  1027→	return iRaiseCnt;
  1028→}
