FROM ubuntu:22.04

ENV DEBIAN_FRONTEND=noninteractive

# Install clang, build tools, and coverage tools
RUN apt-get update && apt-get install -y \
    clang \
    llvm \
    make \
    g++ \
    lcov \
    && rm -rf /var/lib/apt/lists/*

# Set working directory
WORKDIR /workspace

# Copy libco source code
COPY libco /workspace/libco

# Build libco with clang and coverage support
WORKDIR /workspace/libco

# Build object files with clang and coverage flags
RUN clang++ -g -O0 -fprofile-arcs -ftest-coverage \
    -fno-strict-aliasing -Wall -pipe \
    -D_GNU_SOURCE -D_REENTRANT -fPIC -Wno-deprecated -m64 \
    -c co_epoll.cpp -o co_epoll.o && \
    clang++ -g -O0 -fprofile-arcs -ftest-coverage \
    -fno-strict-aliasing -Wall -pipe \
    -D_GNU_SOURCE -D_REENTRANT -fPIC -Wno-deprecated -m64 \
    -c co_hook_sys_call.cpp -o co_hook_sys_call.o && \
    clang++ -g -O0 -fprofile-arcs -ftest-coverage \
    -fno-strict-aliasing -Wall -pipe \
    -D_GNU_SOURCE -D_REENTRANT -fPIC -Wno-deprecated -m64 \
    -c co_routine.cpp -o co_routine.o && \
    clang++ -g -O0 -fprofile-arcs -ftest-coverage \
    -fno-strict-aliasing -Wall -pipe \
    -D_GNU_SOURCE -D_REENTRANT -fPIC -Wno-deprecated -m64 \
    -c coctx.cpp -o coctx.o && \
    clang -g -O0 -fprofile-arcs -ftest-coverage \
    -fno-strict-aliasing -Wall -pipe \
    -D_GNU_SOURCE -D_REENTRANT -fPIC -Wno-deprecated -m64 \
    -c coctx_swap.S -o coctx_swap.o

# Create install directory
RUN mkdir -p /workspace/libco/install

# Create static library
RUN llvm-ar rcs /workspace/libco/install/libco.a \
    co_epoll.o co_hook_sys_call.o co_routine.o coctx.o coctx_swap.o

# Create unit test source for co_resume
RUN cat > /workspace/libco/install/ut_co_resume.cpp << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include "../co_routine.h"

// Test counter to verify execution
static int test_counter = 0;

// Coroutine function for testing co_resume
void* test_coroutine(void* arg)
{
    test_counter++;
    printf("In coroutine: test_counter = %d\n", test_counter);

    // Yield back to main
    co_yield_ct();

    test_counter++;
    printf("Back in coroutine: test_counter = %d\n", test_counter);

    return NULL;
}

int main(int argc, char** argv)
{
    printf("Starting co_resume unit test\n");

    stCoRoutine_t* co = NULL;

    // Create a coroutine
    int ret = co_create(&co, NULL, test_coroutine, NULL);
    if (ret != 0) {
        printf("FAILED: co_create returned %d\n", ret);
        return 1;
    }
    printf("Coroutine created successfully\n");

    // Test co_resume - this should start the coroutine
    printf("Calling co_resume (first time)...\n");
    co_resume(co);

    // Check that coroutine ran
    if (test_counter != 1) {
        printf("FAILED: Expected test_counter=1 after first resume, got %d\n", test_counter);
        return 1;
    }
    printf("First co_resume succeeded: test_counter = %d\n", test_counter);

    // Test co_resume again - this should resume from yield point
    printf("Calling co_resume (second time)...\n");
    co_resume(co);

    // Check that coroutine ran to completion
    if (test_counter != 2) {
        printf("FAILED: Expected test_counter=2 after second resume, got %d\n", test_counter);
        return 1;
    }
    printf("Second co_resume succeeded: test_counter = %d\n", test_counter);

    // Clean up
    co_release(co);
    printf("Coroutine released successfully\n");

    printf("\n=== co_resume unit test PASSED ===\n");
    return 0;
}
EOF

# Build the unit test
RUN clang++ -g -O0 -fprofile-arcs -ftest-coverage \
    -fno-strict-aliasing -Wall -pipe \
    -D_GNU_SOURCE -D_REENTRANT -fPIC -Wno-deprecated -m64 \
    -I/workspace/libco \
    /workspace/libco/install/ut_co_resume.cpp \
    /workspace/libco/install/libco.a \
    -lpthread -ldl \
    -o /workspace/libco/install/ut_co_resume

# Clean up object files and .gcno files from build
RUN rm -f *.o *.gcno

WORKDIR /workspace/libco

CMD ["/bin/bash"]

